import yaml
d=yaml.safe_load(open('tmp/review-triages/feat-review-request-target-dir-151.yaml'))
for i,r in enumerate(d['runs'],1):
    covered={fid for p in (r.get('plans') or []) for fid in p.get('finding_ids',[])}
    for f in r['findings']:
        if f.get('verdict')=='adopted' and f.get('id') not in covered and not f.get('plan_ref'):
            print('uncovered',i,f.get('id'))
    for p in r.get('plans') or []:
        if p.get('status') in ('investigated','pending','awaiting-human'):
            print('open',i,p['problem_id'],p['status'])
# show a done plan example from run 7
p=d['runs'][6]['plans'][0]
print(yaml.safe_dump({k:p[k] for k in p if k in('status','sha','verification','doc_dag','approach','order')},allow_unicode=True,sort_keys=False)[:2500])
EOF
