R=review-triage/skills/review-rally; for id in RR1 RR2 RR3 RR4 RRJ1; do echo "$id: $(grep -l "$id" $R/SKILL.md $R/references/round.md $R/references/session.md $R/references/arguments.md | xargs -n1 basename | tr '\n' ' ')"; done; python3 - <<'EOF'
import re,os
base='review-triage/skills/review-rally'
for root,_,fs in os.walk(base):
    for f in fs:
        if not f.endswith('.md'): continue
        p=os.path.join(root,f); s=open(p).read()
        for m in re.finditer(r'\]\(([^)#]+)(#[^)]*)?\)',s):
            t=m.group(1)
            if t.startswith('http'): continue
            if not os.path.exists(os.path.normpath(os.path.join(root,t))): print('broken',p,t)
print('links checked')
EOF

