cmp2() { PYTHONPATH="$sp" python3 -c "
import compare,json,sys
b=json.loads(sys.argv[1]); a=json.loads(sys.argv[2]); r=compare.compare(b,a)
print('差あり RR1:', r) if r else print('差なし 停止しない')" "$1" "$2"; }
fresh() { rm -rf "$d"/*; git init -q -b main "$d/m"; (cd "$d/m"; git config user.email t@example.invalid; git config user.name t; git commit -q --allow-empty -m a; git branch idle; git worktree add -q -b wt1 ../w1; git worktree add -q -b wt2 ../w2); }
run() { # 説明 期待 操作
  fresh; local b; b=$(snap); ( cd "$d/m"; eval "$3" ) >/dev/null 2>&1; echo "[$1] 期待=$2 / 結果=$(cmp2 "$b" "$(snap)")"; }
cfg='git -C ../w1 config user.email t@example.invalid; git -C ../w1 config user.name t'
run "1 他の worktree のブランチにコミット" 停止しない "git -C ../w1 commit -q --allow-empty -m x"
run "2 別のセッションが新しい worktree でブランチ" 停止しない "git worktree add -q -b wt3 ../w3"
run "3 チェックアウトされていないブランチの SHA" RR1 "git branch -f idle \$(git commit-tree -m z 'HEAD^{tree}')"
run "4a チェックアウトされていないブランチが増えた" RR1 "git branch made"
run "4b チェックアウトされていないブランチが消えた" RR1 "git branch -D idle"
run "5 メインの作業ツリーのブランチの SHA" RR1 "git commit -q --allow-empty -m x"
run "6 メインの作業ツリーの HEAD が別のブランチに" RR1 "git switch -q idle"
run "7 メインの作業ツリーが detached に" RR1 "git switch -q --detach"
run "8 依頼の後に worktree が消えてブランチだけ残る" 停止しない "git worktree remove --force ../w1"
run "9 別のループが起動し -B で切り替え" 停止しない "git worktree add -q -b rev2 ../w3; git -C ../w3 checkout -q -B rev2 HEAD"
run "10 同じ別のループが --detach で切り替えた場合" RR1 "git worktree add -q -b rev2 ../w3; git -C ../w3 checkout -q --detach HEAD"
run "11 GIT_DIR=共通の .git でコミットとブランチ作成" RR1 "c=\$(git rev-parse --git-common-dir); GIT_DIR=\$c git -c user.email=t@example.invalid -c user.name=t commit -q --allow-empty -m rogue; GIT_DIR=\$c git branch br"
fresh; (cd "$d/m"; git switch -q --detach); b=$(snap); (cd "$d/m"; git commit -q --allow-empty -m det); echo "[12 メインが detached のまま SHA が変わる] 期待=RR1 (SHA で比べる) / 結果=$(cmp2 "$b" "$(snap)")"
fresh; b=$(snap); (cd "$d/w1"; git status --porcelain >/dev/null); echo "[13 何も起きない] 期待=停止しない / 結果=$(cmp2 "$b" "$(snap)")"
echo "--- main_head の値 ---"; fresh; snap | python3 -c "import json,sys; d=json.load(sys.stdin); print(d['main_head'], d['worktree_branches'])"
cd /; rm -rf "$d"
EOF
